using AeroCompliance.ApiService.Authorization; using AeroCompliance.ApiService.Services; using AeroCompliance.Contracts.Dtos.Common; using AeroCompliance.Contracts.Dtos.Gis; using AeroCompliance.Domain.Entities; using AeroCompliance.Infrastructure.Persistence; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AeroCompliance.ApiService.Controllers;
[ApiController,Route("api/parcels"),Authorize] public sealed class ParcelsController(AeroComplianceDbContext db,ICurrentUserContext user,IAuditService audit):ControllerBase
{
 [HttpGet] public async Task<ActionResult<PagedResponse<ParcelSummaryDto>>> List(int page=1,int pageSize=25,Guid? blockId=null,string? search=null,CancellationToken ct=default){if(!ApiSupport.IsValidPagination(page,pageSize))return Problem(statusCode:400,title:"Invalid pagination");IQueryable<Parcel> q=Visible().AsNoTracking().Include(x=>x.Block).ThenInclude(b=>b.Zone);if(blockId.HasValue)q=q.Where(x=>x.BlockId==blockId);var s=ApiSupport.NormalizeSearch(search);if(s is not null)q=q.Where(x=>x.ParcelNumber.ToLower().Contains(s));var total=await q.CountAsync(ct);var rows=await q.OrderBy(x=>x.ParcelNumber).Skip((page-1)*pageSize).Take(pageSize).ToListAsync(ct);return Ok(new PagedResponse<ParcelSummaryDto>(rows.Select(MapSummary).ToList(),page,pageSize,total,total==0?0:(int)Math.Ceiling(total/(double)pageSize)));}
 [HttpGet("{id:guid}")] public async Task<ActionResult<ParcelDetailsDto>> Get(Guid id,CancellationToken ct){var x=await Visible().AsNoTracking().Include(x=>x.Block).ThenInclude(b=>b.Zone).SingleOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return NotFound();var canOwner=user.Role is Roles.Admin or Roles.MunicipalityManager or Roles.Inspector or Roles.Reviewer;return Ok(Map(x,canOwner));}
 [HttpPost,Authorize(Policy=Policies.EditParcels)] public async Task<ActionResult<ParcelDetailsDto>> Create(SaveParcelRequest r,CancellationToken ct){if(!await VisibleBlocks().AnyAsync(x=>x.Id==r.BlockId,ct))return NotFound();if(!GeoJsonService.TryReadMultiPolygon(r.Geometry,out var g,out var e))return Problem(statusCode:400,title:"Invalid GeoJSON geometry",detail:e);var n=r.ParcelNumber.Trim();if(await db.Parcels.AnyAsync(x=>x.BlockId==r.BlockId&&x.ParcelNumber==n,ct))return Problem(statusCode:409,title:"Conflict",detail:"Parcel number already exists in this block.");var x=new Parcel{Id=Guid.NewGuid(),BlockId=r.BlockId,ParcelNumber=n,OwnerName=r.OwnerName?.Trim(),ZoneType=r.ZoneType?.Trim(),AreaM2=r.AreaM2,Geom=g,Source=r.Source.Trim(),CreatedAt=DateTimeOffset.UtcNow};db.Parcels.Add(x);audit.Add("parcel.create","Parcel",x.Id,after:new{x.BlockId,x.ParcelNumber,x.ZoneType,x.AreaM2,x.Source});await db.SaveChangesAsync(ct);await db.Entry(x).Reference(p=>p.Block).LoadAsync(ct);if(x.Block is not null)await db.Entry(x.Block).Reference(b=>b.Zone).LoadAsync(ct);return CreatedAtAction(nameof(Get),new{id=x.Id},Map(x,user.Role is Roles.Admin or Roles.MunicipalityManager));}
 [HttpPut("{id:guid}"),Authorize(Policy=Policies.EditParcels)] public async Task<ActionResult<ParcelDetailsDto>> Update(Guid id,SaveParcelRequest r,CancellationToken ct){var x=await Visible().SingleOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return NotFound();var block=await VisibleBlocks().Include(b=>b.Zone).SingleOrDefaultAsync(b=>b.Id==r.BlockId,ct);if(block is null)return NotFound();if(!GeoJsonService.TryReadMultiPolygon(r.Geometry,out var g,out var e))return Problem(statusCode:400,title:"Invalid GeoJSON geometry",detail:e);var n=r.ParcelNumber.Trim();if(await db.Parcels.AnyAsync(p=>p.Id!=id&&p.BlockId==r.BlockId&&p.ParcelNumber==n,ct))return Problem(statusCode:409,title:"Conflict");var before=new{x.BlockId,x.ParcelNumber,x.ZoneType,x.AreaM2,x.Source};x.BlockId=r.BlockId;x.Block=block;x.ParcelNumber=n;x.OwnerName=r.OwnerName?.Trim();x.ZoneType=r.ZoneType?.Trim();x.AreaM2=r.AreaM2;x.Geom=g;x.Source=r.Source.Trim();audit.Add("parcel.update","Parcel",id,before,new{x.BlockId,x.ParcelNumber,x.ZoneType,x.AreaM2,x.Source});await db.SaveChangesAsync(ct);return Ok(Map(x,user.Role is Roles.Admin or Roles.MunicipalityManager));}
 private IQueryable<Parcel> Visible()=>user.IsPlatformAdmin?db.Parcels:db.Parcels.Where(x=>x.Block.Zone.MunicipalityId==user.MunicipalityId);private IQueryable<Block> VisibleBlocks()=>user.IsPlatformAdmin?db.Blocks:db.Blocks.Where(x=>x.Zone.MunicipalityId==user.MunicipalityId);
 private static ParcelSummaryDto MapSummary(Parcel x)=>new(x.Id,x.BlockId,x.Block?.BlockNumber,x.Block?.Zone?.ZoneNumber,x.ParcelNumber,x.ZoneType,x.AreaM2,GeoJsonService.Write(x.Geom));
 private static ParcelDetailsDto Map(Parcel x,bool owner)=>new(x.Id,x.BlockId,x.Block?.BlockNumber,x.Block?.Zone?.ZoneNumber,x.ParcelNumber,owner?x.OwnerName:null,x.ZoneType,x.AreaM2,GeoJsonService.Write(x.Geom),x.Source,x.CreatedAt);
}
